import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.PriorityQueue;

public class HeapsTour {
    public static void main(String[] args) {
        int[] scores = {72, 95, 61, 88, 79, 99, 84, 68, 91};

        // Top 3 with a size-3 min-heap: the root is the weakest of the current top 3
        PriorityQueue<Integer> top = new PriorityQueue<>();
        for (int s : scores) {
            top.offer(s);
            if (top.size() > 3) top.poll();          // drop the smallest: O(log k)
        }
        List<Integer> best = new ArrayList<>(top);
        Collections.sort(best, Collections.reverseOrder());
        System.out.println("top 3 scores: " + best);

        // Running median with two heaps: lower half (max-heap) and upper half (min-heap)
        PriorityQueue<Integer> lower = new PriorityQueue<>(Collections.reverseOrder());
        PriorityQueue<Integer> upper = new PriorityQueue<>();
        StringBuilder medians = new StringBuilder();
        for (int s : scores) {
            lower.offer(s);
            upper.offer(lower.poll());                   // keep every lower value <= every upper value
            if (upper.size() > lower.size()) lower.offer(upper.poll());   // lower may hold one extra
            double median = lower.size() > upper.size() ? lower.peek() : (lower.peek() + upper.peek()) / 2.0;
            medians.append(median).append(' ');
        }
        System.out.println("running medians: " + medians.toString().trim());
    }
}

import java.util.ArrayList;
import java.util.List;

public class MinHeap {
    private final List<Integer> heap = new ArrayList<>();

    void offer(int value) {
        heap.add(value);                               // next free leaf
        int i = heap.size() - 1;
        while (i > 0) {
            int parent = (i - 1) / 2;
            if (heap.get(parent) <= heap.get(i)) break;
            System.out.println("    swap " + heap.get(i) + " up with parent " + heap.get(parent));
            swap(i, parent);
            i = parent;
        }
    }

    int poll() {
        int min = heap.get(0);
        int last = heap.remove(heap.size() - 1);
        if (!heap.isEmpty()) {
            heap.set(0, last);                         // last leaf becomes the root
            int i = 0;
            while (true) {
                int left = 2 * i + 1, right = 2 * i + 2, smallest = i;
                if (left < heap.size() && heap.get(left) < heap.get(smallest)) smallest = left;
                if (right < heap.size() && heap.get(right) < heap.get(smallest)) smallest = right;
                if (smallest == i) break;
                System.out.println("    swap " + heap.get(i) + " down with child " + heap.get(smallest));
                swap(i, smallest);
                i = smallest;
            }
        }
        return min;
    }

    void swap(int a, int b) {
        int t = heap.get(a);
        heap.set(a, heap.get(b));
        heap.set(b, t);
    }

    public static void main(String[] args) {
        MinHeap h = new MinHeap();
        for (int v : new int[]{5, 3, 8, 4, 7, 1}) {
            System.out.println("offer " + v);
            h.offer(v);
            System.out.println("  heap " + h.heap);
        }
        System.out.println("peek = " + h.heap.get(0));
        StringBuilder order = new StringBuilder();
        for (int i = 0; i < 3; i++) {
            System.out.println("poll");
            order.append(h.poll()).append(' ');
            System.out.println("  heap " + h.heap);
        }
        System.out.println("polled in order: " + order.toString().trim());
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

public class MaxHeap {
    private final List<Integer> heap = new ArrayList<>();

    void offer(int value) {
        heap.add(value);
        int i = heap.size() - 1;
        while (i > 0 && heap.get((i - 1) / 2) < heap.get(i)) {   // flipped: bigger goes up
            int parent = (i - 1) / 2;
            int t = heap.get(i); heap.set(i, heap.get(parent)); heap.set(parent, t);
            i = parent;
        }
    }

    record Player(String name, int score) {}

    public static void main(String[] args) {
        MaxHeap h = new MaxHeap();
        int[] scores = {64, 97, 71, 85, 97, 58, 90};
        for (int s : scores) {
            h.offer(s);
            System.out.println("offer " + s + " -> " + h.heap + " (max " + h.heap.get(0) + ")");
        }

        PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.reverseOrder());
        for (int s : scores) pq.offer(s);
        List<Integer> desc = new ArrayList<>();
        while (!pq.isEmpty()) desc.add(pq.poll());
        System.out.println("PriorityQueue(reverseOrder) polls: " + desc);

        String[] names = {"kai", "ana", "lee", "bo", "zed", "mo", "eve"};
        PriorityQueue<Player> board = new PriorityQueue<>(
                Comparator.comparingInt(Player::score).reversed().thenComparing(Player::name));
        for (int i = 0; i < names.length; i++) board.offer(new Player(names[i], scores[i]));
        StringBuilder sb = new StringBuilder();
        while (!board.isEmpty()) {
            Player p = board.poll();
            sb.append(p.name()).append('=').append(p.score()).append(' ');
        }
        System.out.println("leaderboard: " + sb.toString().trim());
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class HeapOperations {
    static List<Integer> heap = new ArrayList<>();
    static int comparisons;

    static boolean less(int i, int j) { comparisons++; return heap.get(i) < heap.get(j); }

    static void swap(int i, int j) { int t = heap.get(i); heap.set(i, heap.get(j)); heap.set(j, t); }

    static void siftUp(int i) {
        while (i > 0 && less(i, (i - 1) / 2)) { swap(i, (i - 1) / 2); i = (i - 1) / 2; }
    }

    static void siftDown(int i) {
        while (true) {
            int l = 2 * i + 1, r = 2 * i + 2, m = i;
            if (l < heap.size() && less(l, m)) m = l;
            if (r < heap.size() && less(r, m)) m = r;
            if (m == i) return;
            swap(i, m);
            i = m;
        }
    }

    static boolean isHeap(List<Integer> a) {
        for (int i = 1; i < a.size(); i++) if (a.get((i - 1) / 2) > a.get(i)) return false;   // parent <= child
        return true;
    }

    static int replaceTop(int value) {
        int old = heap.get(0);
        heap.set(0, value);
        siftDown(0);
        return old;
    }

    static void removeAt(int i) {
        int last = heap.remove(heap.size() - 1);
        if (i == heap.size()) return;              // removed the last slot itself
        heap.set(i, last);
        siftDown(i);
        siftUp(i);                                 // only one of the two will move it
    }

    public static void main(String[] args) {
        System.out.println("isHeap [1, 3, 2, 7, 4, 5] = " + isHeap(Arrays.asList(1, 3, 2, 7, 4, 5)));
        System.out.println("isHeap [1, 3, 2, 7, 0, 5] = " + isHeap(Arrays.asList(1, 3, 2, 7, 0, 5)));

        for (int v = 1; v <= 15; v++) heap.add(v * 10);      // sorted ascending is a valid min-heap
        System.out.println("heap: " + heap);
        comparisons = 0;
        int old = replaceTop(125);
        System.out.println("replaceTop(125) removed " + old + " using " + comparisons + " comparisons -> " + heap);

        comparisons = 0;
        int index = heap.indexOf(40);                          // O(n) search: heaps have no index
        removeAt(index);
        System.out.println("remove 40 at index " + index + " using " + comparisons + " comparisons -> " + heap);
        System.out.println("still a heap? " + isHeap(heap));
    }
}

import java.util.Arrays;

public class Heapify {
    static int swaps;

    static void siftDown(int[] a, int i, int n) {
        while (true) {
            int l = 2 * i + 1, r = 2 * i + 2, m = i;
            if (l < n && a[l] < a[m]) m = l;
            if (r < n && a[r] < a[m]) m = r;
            if (m == i) return;
            int t = a[i]; a[i] = a[m]; a[m] = t;
            swaps++;
            i = m;
        }
    }

    static void heapify(int[] a, boolean trace) {
        for (int i = a.length / 2 - 1; i >= 0; i--) {     // last parent down to the root
            siftDown(a, i, a.length);
            if (trace) System.out.println("  sift down index " + i + ": " + Arrays.toString(a));
        }
    }

    static void insertOneByOne(int[] values) {
        int[] heap = new int[values.length];
        for (int n = 0; n < values.length; n++) {
            heap[n] = values[n];
            int i = n;
            while (i > 0 && heap[(i - 1) / 2] > heap[i]) {
                int p = (i - 1) / 2;
                int t = heap[i]; heap[i] = heap[p]; heap[p] = t;
                swaps++;
                i = p;
            }
        }
    }

    public static void main(String[] args) {
        int[] a = {9, 4, 7, 1, 8, 2, 6, 3, 5};
        System.out.println("heapify " + Arrays.toString(a) + " (last parent is index " + (a.length / 2 - 1) + "):");
        heapify(a, true);

        int n = 255;
        int[] reversed = new int[n];
        for (int i = 0; i < n; i++) reversed[i] = n - i;
        swaps = 0;
        heapify(reversed.clone(), false);
        int heapifySwaps = swaps;
        swaps = 0;
        insertOneByOne(reversed);
        System.out.println(n + " values in reverse order: heapify " + heapifySwaps + " swaps, one-by-one offer " + swaps + " swaps");
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.PriorityQueue;

public class PriorityQueues {
    record Event(int time, int seq, String name) {}

    public static void main(String[] args) {
        int[] stream = {41, 7, 93, 18, 66, 2, 85, 30, 77, 54};
        PriorityQueue<Integer> topK = new PriorityQueue<>();
        for (int x : stream) {
            if (topK.size() < 3) topK.offer(x);
            else if (x > topK.peek()) {                   // beats the weakest of the top 3
                topK.poll();
                topK.offer(x);
            }
        }
        List<Integer> top = new ArrayList<>(topK);
        Collections.sort(top);
        System.out.println("3 largest: " + top);

        int[][] lists = {{1, 4, 9}, {2, 3, 11}, {5, 6, 7, 20}};
        PriorityQueue<int[]> heads = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));   // {value, list, index}
        for (int i = 0; i < lists.length; i++) heads.offer(new int[]{lists[i][0], i, 0});
        List<Integer> merged = new ArrayList<>();
        while (!heads.isEmpty()) {
            int[] h = heads.poll();
            merged.add(h[0]);
            int next = h[2] + 1;
            if (next < lists[h[1]].length) heads.offer(new int[]{lists[h[1]][next], h[1], next});
        }
        System.out.println("merged k lists: " + merged);

        PriorityQueue<Event> events = new PriorityQueue<>((a, b) ->
                a.time() != b.time() ? Integer.compare(a.time(), b.time()) : Integer.compare(a.seq(), b.seq()));
        int seq = 0;
        events.offer(new Event(0, seq++, "open"));
        events.offer(new Event(5, seq++, "customer A"));
        events.offer(new Event(2, seq++, "customer B"));
        while (!events.isEmpty()) {
            Event e = events.poll();
            System.out.println("t=" + e.time() + " " + e.name());
            if (e.name().startsWith("customer")) {
                events.offer(new Event(e.time() + 3, seq++, "done " + e.name().substring(9)));   // schedule the future
            }
        }
    }
}

